select (to_regclass('public.student_admin_statuses') is not null) and (to_regclass('public.student_admin_notes') is not null) and (to_regclass('public.student_weekly_plans') is not null) and (to_regclass('public.student_weekly_plan_items') is not null) and (to_regclass('public.student_activity_events') is not null) and exists (select 1 from pg_proc where pronamespace='public'::regnamespace and proname='complete_weekly_plan_item') and not has_table_privilege('anon','public.student_activity_events','INSERT') and not has_table_privilege('anon','public.student_weekly_plans','SELECT') and not has_function_privilege('anon','public.complete_weekly_plan_item(uuid,boolean)','EXECUTE') as ok;
